extends SceneTree

# Temporary verification script. Deleted after use.
# Runs the main scene with a simple bot: for the first 420 frames it jumps each
# hurdle at the right moment; after that it stops jumping so knock-downs happen.
var _frame := 0
var _main: Node
var _jumped := {}
var _pending_release := false
var _shot_taken := false


func _initialize() -> void:
	change_scene_to_file("res://main.tscn")


func _process(_delta: float) -> bool:
	_frame += 1
	if _pending_release:
		_send_jump(false)
		_pending_release = false
	if _main == null:
		_main = root.get_node_or_null("Main")
		return false
	if _frame <= 420:
		_bot()
	if not _shot_taken and float(_main.get("_height")) > 1.0:
		_save("res://_shot_jump.png")
		_shot_taken = true
	if _frame % 300 == 0:
		print("frame ", _frame, " distance ", snappedf(float(_main.get("_distance")), 0.1),
			" height ", snappedf(float(_main.get("_height")), 0.01),
			" cleared ", _main.get("_cleared"), " knocked ", _main.get("_knocked"))
	if _frame == 1500:
		_save("res://_shot_run.png")
		print("final cleared ", _main.get("_cleared"), " knocked ", _main.get("_knocked"))
		return true
	return false


func _bot() -> void:
	var hurdles: Array = _main.get("_hurdles")
	var distance := float(_main.get("_distance"))
	for hurdle in hurdles:
		if hurdle["resolved"]:
			continue
		var gap := float(hurdle["distance"]) - distance
		var key := str(hurdle["distance"])
		if gap >= 4.2 and gap <= 4.6 and float(_main.get("_jump_time")) < 0.0 and not _jumped.has(key):
			_jumped[key] = true
			_send_jump(true)
			_pending_release = true
		break


func _send_jump(pressed: bool) -> void:
	var event := InputEventAction.new()
	event.action = "ui_accept"
	event.pressed = pressed
	Input.parse_input_event(event)


func _save(path: String) -> void:
	var image := root.get_texture().get_image()
	image.save_png(ProjectSettings.globalize_path(path))
	print("saved ", path)

